// 凭据只接现有原生真人送信/返报；显式版本决定独立段，能力并集不能给旧情景偷偷升级。
#include "task_message_handoff_profile.hpp"
namespace hanmo::resident {
Outcome<Integer> decode_task_message_handoff_version(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{
    using namespace boundary;object(scenario,"scenario");const auto* value=scenario.find("task_message_handoff_profile");if(!value)return {true,0,{}};
    const auto name=string(*value,"scenario/task_message_handoff_profile");const Integer version=name=="observed_letter_delivery_v1"?1:name=="observed_letter_delivery_and_report_v2"?2:name=="known_personal_delivery_and_report_v3"?3:name=="known_personal_delivery_and_sender_report_v4"?4:0;if(!version)unsupported("UnsupportedTaskMessageHandoffProfile","scenario/task_message_handoff_profile");
    for(const auto* capability:{"task_message_handoffs_v1","tasks.message","native_dynamic_world","dialogue","multi_actor"})if(std::find(capabilities.begin(),capabilities.end(),capability)==capabilities.end())unsupported("MissingTaskMessageHandoffCapability",capability);if(version>=2&&std::find(capabilities.begin(),capabilities.end(),"task_message_reports_v2")==capabilities.end())unsupported("MissingTaskMessageHandoffCapability","task_message_reports_v2");
    const auto* dynamic=scenario.find("dynamic_world");const auto* native=dynamic?dynamic->find("profile"):nullptr;if(!native||string(*native,"scenario/dynamic_world/profile")!="local_society_v1")unsupported("TaskMessageHandoffNativeProfileRequired","scenario/dynamic_world/profile");if(version==3||version==4){if(std::find(capabilities.begin(),capabilities.end(),"task_personal_message_deliveries_v1")==capabilities.end())unsupported("MissingTaskMessageHandoffCapability","task_personal_message_deliveries_v1");const auto* personal=dynamic->find("task_personal_message_deliveries");if(!personal||get_int(*personal,"version","task_personal_message_deliveries")!=1||get_string(*personal,"profile","task_personal_message_deliveries")!="known_private_recipient_v1")unsupported("TaskPersonalMessageProfileRequired","task_personal_message_deliveries");}if(version==4){if(std::find(capabilities.begin(),capabilities.end(),"task_personal_message_reports_v1")==capabilities.end())unsupported("MissingTaskMessageHandoffCapability","task_personal_message_reports_v1");const auto* report=dynamic->find("task_personal_message_reports");if(!report||get_int(*report,"version","task_personal_message_reports")!=1||get_string(*report,"profile","task_personal_message_reports")!="known_private_sender_report_v1")unsupported("TaskPersonalReportProfileRequired","task_personal_message_reports");}return {true,version,{}};
}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
// 旧bool入口严格保持只能选择v1；共享候选未升级时不能把新作者值压成true后错误写旧版本。
Outcome<bool> decode_task_message_handoff_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){auto version=decode_task_message_handoff_version(scenario,capabilities);if(!version.ok)return {false,{},version.error};if(version.value>1)return {false,{},common_failure("UnsupportedTaskMessageHandoffProfile").error};return {true,version.value==1,{}};}
}
